/* OFL fonts; optional prevents a late font swap after first text paint. */
@font-face{font-family:"Noto Sans KR";font-style:normal;font-weight:100 900;font-display:optional;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"IBM Plex Mono";font-style:normal;font-weight:400;font-display:optional;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"IBM Plex Mono";font-style:normal;font-weight:500;font-display:optional;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"Space Grotesk";font-style:normal;font-weight:300 700;font-display:optional;src:url(data:font/woff2;base64,) format("woff2");}
